def generation():
    parent = ROOT / 'kg_datasets/dblp/course_v4_training_inputs_12'
    queue = parent / 'pending_generation.jsonl'
    assert c.file_sha256(parent / 'manifest.json') == '991b6584799240d2969c7f94e6f7b957b41e546aa558a451c58ef029a7056ff1'
    assert c.file_sha256(queue) == 'fea3a75a0cf5b80ffa00d0e28d94075a7a2466a6536a447242da3cdd2d3afb39'
    jobs = c.read_jsonl(queue)[:100]
    assert len(jobs) == 100 and [d['index'] for d in DECISIONS] == list(range(100))
    refs = {r['sampleId']: r for r in c.read_jsonl(ROOT / 'kg_datasets/dblp/course_v4_weak/references.jsonl')}
    prior = {r['reference']['sampleId'] for r in c.read_jsonl(parent / 'receipts.jsonl')}
    assert all(refs[j['sampleId']]['split'] == 'train' for j in jobs)
    assert not prior.intersection(j['sampleId'] for j in jobs)
    output = ROOT / 'kg_datasets/dblp/course_v4_runs/pending_train_20261007_20'
    output.mkdir(exist_ok=False)
    c.write_jsonl(output / 'jobs.jsonl', jobs)
    c.write_json(output / 'generation_decisions.json', {'provider':'codex_session', 'model':'unknown_session_model',
        'round':'generation', 'decisions':[{k:v for k,v in d.items() if k!='index'} | {'sampleId':j['sampleId']}
                                         for d,j in zip(DECISIONS,jobs)]})
    shutil.copyfile(Path(__file__), output / 'authored_generation.py')
    compiled = output / 'generation_compiled'
    dataset = ROOT / 'kg_datasets/dblp/course_v4_weak'
    compile_artifact(dataset, output / 'jobs.jsonl', output / 'generation_decisions.json', compiled)
    result = import_results(dataset, compiled / 'responses.jsonl', output / 'generation', provider='codex_session', model='unknown_session_model')
    print({'documents':result['generationReceiptDocuments'], 'generationDecisionsSha256':c.file_sha256(output / 'generation_decisions.json')})


if __name__ == '__main__':
    generation()
